import{t as e}from"./utils-COoNfFoj.js";var t={slug:`cool-worlds`,influencerName:`Cool Worlds`,influencerHandle:`@CoolWorlds`,influencerAvatarUrl:`${e}/cool-worlds-avatar.jpg`,heroDescription:`My video is about something known as the Berserker Hypothesis - or really a variant of it. It considers the possibility that alien civilizations might construct self-replicating machines that spread out amongst the stars, essentially acting like an infection wavefront - converting all normal matter into computational substrate. I have developed a cosmological model to calculate what fraction of galaxies would be infected by the current age of the Universe given various inputs. In this app, the user can play around with the inputs for themselves to produce realistic looking 3D maps of the infected volume software space.`,assetTitle:`Berserker Intergalactic Infection Snapshot`,screenshotUrl:`${e}/cool-worlds.png`,remixUrl:`https://www.perplexity.ai/computer/a/ab65f0cf-f9ca-414d-98cb-f8ef19301efe`,promptTitle:`Try Cool Worlds' prompt`,promptText:`Build an interactive Flask + three.js app visualizing a stochastic cosmological propagation process in a 1 Gpc³ box on a 64³ voxel grid, using Planck 2018 ΛCDM with z_start=10. Implement a two-stage snapshot — internal Poisson seeds plus an external bubble correction with shell-volume-weighted proposals — with an earliest-seed-wins rule coloring each voxel by its earliest enclosing seed's redshift. Provide sidebar log sliders for seeding rate λ and speed u, a cosmic-time slider, RNG seed, and re-roll, debouncing changes to re-render with a loading indicator and a warm-to-cool redshift palette.`};export{t as default};
